/// SEED ECB encryption (RFC 4269 §2, SP 800-38A §6.1) of `n` complete 16-byte blocks at `data`, in place, under the schedule written by `vg_seed_expand_key`. No padding is added or removed. For `n = 0`, no data is transformed.
///
/// Contract: `VG.Spec.Seed.ecbEncryptContract`. Constant time: only pointers and `n` may affect timing, not the schedule or data, including S-box inputs.
///
/// It returns without secret residue: what it leaves in the registers, the flags and the stack below the caller's stack pointer is determined by what its caller left there and by public data (`Target.noResidue`).
///
/// # Safety
///
/// * `schedule` must be valid for reads of 128 bytes.
/// * `data` must be valid for reads and writes of `16 * n` bytes.
/// * `data` must not overlap `schedule` (distinct Rust objects never do).
/// * Neither `schedule` nor `data` may overlap the 760 bytes of stack below the stack pointer, or wrap around the end of the address space (no Rust object does).
#[unsafe(naked)]
pub(crate) unsafe extern "C" fn vg_seed_ecb_encrypt(schedule: *const [u8; 128], data: *mut [u8; 16], n: usize) {
    core::arch::naked_asm!(
        r"push {{r4, lr}}
mov r4, lr
bl {vg_seed_ecb_encrypt_core}
mov lr, r4
ldr r4, [sp], #8
sub sp, sp, #760
add r12, sp, #0
mov r2, #0
mov r3, #23
20:
str r2, [r12, #0]
str r2, [r12, #4]
str r2, [r12, #8]
str r2, [r12, #12]
str r2, [r12, #16]
str r2, [r12, #20]
str r2, [r12, #24]
str r2, [r12, #28]
add r12, r12, #32
subs r3, r3, #1
bne 20b
str r2, [r12, #0]
str r2, [r12, #4]
str r2, [r12, #8]
str r2, [r12, #12]
str r2, [r12, #16]
str r2, [r12, #20]
add sp, sp, #760
mov r0, #0
mov r1, #0
mov r2, #0
mov r3, #0
mov r12, #0
cmp r2, r2
bx lr",
        vg_seed_ecb_encrypt_core = sym super::seed::vg_seed_ecb_encrypt_core::vg_seed_ecb_encrypt_core,
    )
}

